CREATE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=clock_timestamp(); RETURN NEW; END $$;
CREATE TABLE course(course_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(200) NOT NULL CHECK(char_length(btrim(name))>0),name_normalized text NOT NULL UNIQUE CHECK(char_length(name_normalized)>0),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE level(level_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES course(course_id) ON DELETE RESTRICT,name varchar(200) NOT NULL CHECK(char_length(btrim(name))>0),name_normalized text NOT NULL CHECK(char_length(name_normalized)>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(course_id,name_normalized));
CREATE TABLE course_module(module_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),course_id uuid NOT NULL REFERENCES course(course_id) ON DELETE RESTRICT,title varchar(200) NOT NULL CHECK(char_length(btrim(title))>0),title_normalized text NOT NULL CHECK(char_length(title_normalized)>0),order_no integer NOT NULL CHECK(order_no>0),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(course_id,title_normalized),UNIQUE(course_id,order_no));
CREATE TABLE lesson(lesson_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),module_id uuid NOT NULL REFERENCES course_module(module_id) ON DELETE RESTRICT,title varchar(200) NOT NULL CHECK(char_length(btrim(title))>0),title_normalized text NOT NULL CHECK(char_length(title_normalized)>0),content text NOT NULL CHECK(char_length(btrim(content))>0 AND char_length(content)<=20000),order_no integer NOT NULL CHECK(order_no>0),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(module_id,title_normalized),UNIQUE(module_id,order_no));
CREATE TABLE vocabulary(vocabulary_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lesson_id uuid NOT NULL REFERENCES lesson(lesson_id) ON DELETE RESTRICT,word varchar(128) NOT NULL CHECK(char_length(btrim(word))>0),meaning varchar(500) NOT NULL CHECK(char_length(btrim(meaning))>0),example varchar(1000),phonetic varchar(128),word_normalized text NOT NULL CHECK(char_length(word_normalized)>0),meaning_normalized text NOT NULL CHECK(char_length(meaning_normalized)>0),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(lesson_id,word_normalized,meaning_normalized));
CREATE TABLE learning_content(content_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lesson_id uuid NOT NULL REFERENCES lesson(lesson_id) ON DELETE RESTRICT,type varchar(16) NOT NULL CHECK(type IN ('GRAMMAR','LISTENING','READING')),title varchar(200) NOT NULL CHECK(char_length(btrim(title))>0),text text CHECK(text IS NULL OR (char_length(btrim(text))>0 AND char_length(text)<=20000)),resource_url varchar(2048) CHECK(resource_url IS NULL OR resource_url ~ '^https://'),published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((type IN ('GRAMMAR','READING') AND text IS NOT NULL) OR (type='LISTENING' AND resource_url IS NOT NULL)));
CREATE TABLE user_vocabulary(user_vocabulary_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,vocabulary_id uuid NOT NULL REFERENCES vocabulary(vocabulary_id) ON DELETE RESTRICT,added_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,vocabulary_id));
CREATE INDEX lessons_module ON lesson(module_id,order_no,lesson_id);
CREATE INDEX modules_course ON course_module(course_id,order_no,module_id);
CREATE INDEX contents_lesson ON learning_content(lesson_id,type,content_id);
CREATE INDEX saved_list ON user_vocabulary(user_id,user_vocabulary_id);
CREATE TRIGGER course_timestamp BEFORE UPDATE ON course FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER level_timestamp BEFORE UPDATE ON level FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER course_module_timestamp BEFORE UPDATE ON course_module FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER lesson_timestamp BEFORE UPDATE ON lesson FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER vocabulary_timestamp BEFORE UPDATE ON vocabulary FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER learning_content_timestamp BEFORE UPDATE ON learning_content FOR EACH ROW EXECUTE FUNCTION set_updated_at();
GRANT SELECT,INSERT,UPDATE ON course,level,course_module,lesson,vocabulary,learning_content TO content_runtime;
GRANT SELECT,INSERT,DELETE ON user_vocabulary TO content_runtime;
GRANT USAGE ON SCHEMA public TO content_runtime;
